// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }

    function testFuzz_property(uint256 seed, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: caller has a positive balance enough for an outer withdrawal,
        // and the inner reentrant attempt uses the same amount (<= caller's balance at entry).
        amount = bound(amount, 1, 1e30);

        Reenterer attacker = new Reenterer(address(c), amount);
        address caller = address(attacker);
        vm.deal(caller, amount);

        // Give the caller a balance by depositing via the attacker's funded balance.
        vm.prank(caller);
        c.Deposit{value: amount}();

        // The attacker re-enters CashOut once during the outer call, before state is written
        // in the mutant (or after in the reference).
        attacker.arm();
        vm.prank(caller);
        c.CashOut(amount);

        // Reference: balance went from `amount` to 0 exactly once (inner attempt rejected).
        // Mutant: inner attempt succeeded because subtraction happened after the call,
        // leaving the balance inconsistent (or the outer subtraction underflows/reverts).
        assertTrue(c.balances(caller) == 0);
    }
}

contract Reenterer {
    PrivateBank private c;
    uint256 private am;
    bool private armed;
    bool private entered;

    constructor(address _c, uint256 _am) { c = PrivateBank(payable(_c)); am = _am; }
    function arm() external { armed = true; }

    receive() external payable {
        if (armed && !entered) {
            entered = true;
            c.CashOut(am);
        }
    }
}
